-- 0005_media (Phase 6A): metadata of generated results stored in the private R2 bucket (MEDIA).
--
-- The object key is always generated by the API (media/<project>/<job>/<media id>.<ext>); a client can
-- never choose it. Downloads go through media ids only, never through jobs.result_key.
--
-- Plain TEXT references (no foreign keys), like jobs.retry_of: history and a future cleanup job can
-- never be blocked by, or cascade into, this table. UNIQUE(job_id, sha256) makes a worker's retry of
-- the same upload an idempotent replay instead of a duplicate object.
CREATE TABLE IF NOT EXISTS media (
  id TEXT PRIMARY KEY,
  job_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  scene_id TEXT,
  kind TEXT NOT NULL CHECK (kind IN ('video','image')),
  mime TEXT NOT NULL CHECK (mime IN ('video/mp4','video/webm','image/png','image/jpeg','image/webp')),
  -- Upper bound mirrors MAX_MEDIA_BYTES in apps/api/src/media-routes.ts (90 MiB).
  size_bytes INTEGER NOT NULL CHECK (size_bytes > 0 AND size_bytes <= 94371840),
  -- Lower-case hex SHA-256 of the stored bytes, verified by R2 at upload time.
  sha256 TEXT NOT NULL CHECK (length(sha256) = 64 AND sha256 NOT GLOB '*[^0-9a-f]*'),
  r2_key TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (job_id, sha256)
);
CREATE INDEX IF NOT EXISTS idx_media_job ON media(job_id, created_at, id);
CREATE INDEX IF NOT EXISTS idx_media_project ON media(project_id, created_at, id);
